from pathlib import Path
import runpy

root=Path(__file__).resolve().parents[2]
ctx=runpy.run_path(str(root/'output/stock-preview/create-variants.py'))
base,common,compact,tablejs,table_row=[ctx[k] for k in ['base','common','compact','tablejs','table_row']]

thumbcss='''
.app{grid-template-columns:74px 490px minmax(0,1fr)}.sidebar .list{margin:0}.table-head,.model-facets{display:none}.thumb-row{width:100%;display:grid;grid-template-columns:108px 1fr;gap:14px;padding:21px 22px;border-bottom:1px solid var(--line);text-align:left;position:relative;min-height:134px}.thumb-row.selected{background:#edf3fe}.thumb-row.selected:before{content:'';position:absolute;left:0;top:15px;bottom:15px;width:3px;background:#2467d1}.thumb-row img{width:108px;height:83px;object-fit:contain}.thumb-info{min-width:0}.thumb-info .row{margin:0 0 11px}.thumb-info strong{font-size:16px;font-weight:600}.thumb-info strong small{font-size:12px;color:#73839a;font-weight:400;margin-left:4px}.thumb-info .status{font-size:10px}.thumb-info .vin{font-size:10px;margin:0 0 10px;color:#647c9b}.thumb-info .meta{font-size:11px;color:var(--muted)}main{padding:28px 40px 0}.hero{min-height:265px}.hero img{max-height:225px}.facts{margin-bottom:25px}.details{gap:25px}.timeline .event{min-height:52px}.data-row{min-height:52px}.column{padding-right:25px}.sectiontitle,.tabs{height:43px}.actions{min-height:71px}.breadcrumb{margin-bottom:20px}
'''
thumbrow='''`<button class="thumb-row ${c.i===selected?'selected':''}" data-index="${c.i}"><img src="../pictures/${c.image}.webp" alt="${c.model}"><span class="thumb-info"><span class="row"><strong>${c.model}<small>${c.version}</small></strong><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></span><div class="vin">${c.vin}</div><span class="row meta"><span>${c.color} · Black</span><span>${c.age} ngày</span></span><span class="meta">${c.park} · Thuận An</span></span></button>`'''
bottomcss='''
.app{grid-template-columns:74px minmax(0,1fr);grid-template-rows:490px minmax(0,1fr) 32px}.rail{grid-row:1/4}.sidebar{grid-column:2;grid-row:1;border:0;border-bottom:1px solid var(--line)}main{grid-column:2;grid-row:2;border:0;display:grid;grid-template-columns:31% minmax(0,1fr);grid-template-rows:82px minmax(0,1fr) 55px;gap:0 30px;padding:18px 30px 0}.breadcrumb,.titlebar{display:none}.heading{padding:22px 30px 14px}.heading h1{font-size:26px}.searchbar{position:absolute;left:370px;top:18px;width:550px;padding:0}.sidebar{position:relative}.summary{position:absolute;right:28px;top:32px;padding:0;gap:24px}.summary b{font-size:16px}.model-facets{margin-bottom:13px}.model-facets span{padding-bottom:12px}.table-head{padding:10px 16px}.table-row{min-height:36px;padding:8px 16px}.table-row>span:first-child{display:flex;align-items:center;gap:10px}.table-row small{display:inline;margin:0 0 0 8px;font-size:10px}.table-row .t-location small{display:none}.table-row .t-vin{font-size:11px}.table-row strong{font-size:13px}.listfoot{display:none}.sidebar .list{margin-bottom:12px}main .hero{grid-column:1;grid-row:1/3;display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;height:auto;min-height:0;padding:0 25px 0 0;border-right:1px solid var(--line)}main .hero img{height:152px;max-height:152px;padding:0;margin:0 0 8px}main .hero .model{font-size:32px;margin:0 0 10px}.idline>span:last-child{display:none}.idline{font-size:11px}.hero .specs{margin-top:15px;padding-top:13px}main .facts{grid-column:2;grid-row:1;display:flex;align-items:center;gap:0;min-height:0;margin:0 0 18px;padding:0 0 15px;border-top:0}.fact{padding-left:20px!important}.fact:first-child{padding-left:0!important}.facts .fact:nth-child(2){border-right:1px solid var(--line)}.fact strong{font-size:13px}.facts .label{font-size:11px}main .details{grid-column:2;grid-row:2;grid-template-columns:1.1fr 1fr .9fr;gap:25px;margin:0 0 10px}.column:first-child{grid-column:auto;order:0;border-right:1px solid var(--line);padding-right:25px}.column:nth-child(2){padding-right:25px}.column:last-child{border:0}.timeline{display:block;padding-top:7px}.timeline .event{flex-direction:row;align-items:center;max-width:none;min-height:34px;gap:9px;font-size:11px}.event:before{width:1px;height:17px;top:24px;left:10px}.check{width:21px;height:21px}.event time{margin-left:auto;font-size:10px}.sectiontitle{height:32px}.data-row{min-height:34px!important;font-size:11px}.note{font-size:11px}.actions{grid-column:1/3;grid-row:3;min-height:55px!important}.actions .hint{font-size:10px}.tabs{height:32px}.btn{font-size:12px;padding:9px 15px}footer{grid-column:2;grid-row:3}
'''
bottomcss += '.heading .icon{display:none}'
groupcss='''
.sidebar{background:#fbfbfd}.table-head{display:none}.sidebar .list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;overflow:auto;padding-bottom:16px}.lane{min-width:0}.lane-heading{display:flex;align-items:center;justify-content:space-between;padding:0 0 16px;border-bottom:1px solid var(--line);margin-bottom:14px;font-size:13px}.lane-heading small{font-size:11px;color:var(--muted);font-weight:400}.lane-heading .status{font-size:13px;color:#334965}.group-car{display:block;width:100%;padding:18px 16px;background:white;border:1px solid #e3e9f2;border-radius:6px;margin-bottom:12px;text-align:left;position:relative}.group-car.selected{border-color:#82a7dd;background:#f0f5ff}.group-car .row{margin-bottom:11px}.group-car strong{font-size:15px;font-weight:600}.group-car .version{font-size:12px;color:var(--muted)}.group-car .vin{font-size:10px;margin:0 0 10px;color:#5f7797}.group-car .meta{font-size:11px;color:var(--muted)}.group-car .group-foot{display:flex;justify-content:space-between;font-size:11px;border-top:1px solid var(--line);margin-top:12px;padding-top:11px;color:#70849d}.group-car .age{color:#334965}.sidebar .summary{padding-bottom:22px}.model-facets{margin-bottom:24px}
'''
grouprow='''`<button class="group-car ${c.i===selected?'selected':''}" data-index="${c.i}"><span class="row"><strong>${c.model}</strong><span class="version">${c.version}</span></span><div class="vin">${c.vin}</div><div class="meta"><i class="swatch"></i>${c.color} · Black</div><div class="group-foot"><span>${c.park}</span><span class="age">${c.age} ngày</span></div></button>`'''
groupjs=tablejs.replace('ROW',grouprow)
groupjs=groupjs.replace("visible.map(c=>"+grouprow+").join('')", "['Chưa ghép','Đang giữ','Đã ghép'].map(s=>`<section class=\"lane\"><div class=\"lane-heading\"><span class=\"status\" style=\"--tone:${tone(s)}\">${s}</span><small>${visible.filter(c=>c.status===s).length} xe</small></div>${visible.filter(c=>c.status===s).map(c=>"+grouprow+").join('')}</section>`).join('')")

variants=[
('04','Danh sách có ảnh xe',common+thumbcss,tablejs.replace('ROW',thumbrow)),
('05','Bảng xe & chi tiết phía dưới',common+compact+bottomcss,tablejs.replace('ROW',table_row)),
('06','Phân nhóm theo trạng thái',common+compact+groupcss,groupjs),
]
for n,title,css,js in variants:
    html=base.replace('</style>',css+'</style>').replace('</body>','<script>'+js+'</script></body>')
    html=html.replace('Kho xe · Mẫu giao diện','Kho xe · Mẫu '+n+' · '+title).replace('MẪU XEM TRƯỚC · 29/10/2026','MẪU '+n+' · '+title.upper())
    (root/('public/previews/kho-xe-mau-'+n+'.html')).write_text(html,encoding='utf-8')
    print('Created variant '+n)
